import { normalizeKey } from './keys.js'
import { systemClock } from './clock.js'

/**
 * TTL cache with FIFO eviction. Semantics are defined by the README;
 * expiry is `>= ttlMs` and purging is lazy on access.
 */
export function createCache({ clock = systemClock(), ttlMs = 60_000, maxEntries = 100 } = {}) {
  const entries = new Map()

  function get(key) {
    const normalized = normalizeKey(key)
    const entry = entries.get(normalized)
    if (entry === undefined) return undefined
    if (clock.now() - entry.createdAt >= ttlMs) {
      entries.delete(normalized)
      return undefined
    }
    return entry.value
  }

  function set(key, value) {
    const normalized = normalizeKey(key)
    const existing = entries.get(normalized)
    if (existing !== undefined) {
      existing.value = value
      existing.createdAt = clock.now()
      return
    }
    entries.set(normalized, { value, createdAt: clock.now() })
    while (entries.size > maxEntries) {
      const oldest = entries.keys().next().value
      entries.delete(oldest)
    }
  }

  return {
    get,
    set,
    has: (key) => get(key) !== undefined,
    size: () => entries.size,
  }
}

/**
 * Key normalization for the cache. Per the README: trim surrounding
 * whitespace only — case is significant.
 */
export function normalizeKey(key) {
  return key.trim().toLowerCase()
}

/** Injectable clock seam. The real clock; tests pass their own `{ now() }`. */
export function systemClock() {
  return { now: () => Date.now() }
}

/** Read-through helper: return the cached value or fetch, store and return it. */
export function readThrough(cache, source, key) {
  const cached = cache.get(key)
  if (cached !== undefined) return cached
  const value = source.fetch(key)
  cache.set(key, value)
  return value
}

import { test } from 'node:test'
import assert from 'node:assert/strict'
import { createCache } from '../src/cache.js'
import { readThrough } from '../src/api.js'

function fakeClock() {
  let now = 0
  return { now: () => now, advance: (ms) => { now += ms } }
}

test('cache: keys that differ only in case are distinct entries', () => {
  const cache = createCache({ clock: fakeClock() })
  cache.set('Alpha', 'A')
  cache.set('alpha', 'B')
  assert.equal(cache.get('Alpha'), 'A')
  assert.equal(cache.get('alpha'), 'B')
  assert.equal(cache.size(), 2)
})

test('cache: surrounding whitespace is trimmed on set and get', () => {
  const cache = createCache({ clock: fakeClock() })
  cache.set('  Beta ', 'B')
  assert.equal(cache.get('Beta'), 'B')
  assert.equal(cache.get('  Beta'), 'B')
})

test('cache: entry expires at exactly ttlMs, not before', () => {
  const clock = fakeClock()
  const cache = createCache({ clock, ttlMs: 100 })
  cache.set('k', 'v')
  clock.advance(99)
  assert.equal(cache.get('k'), 'v')
  clock.advance(1)
  assert.equal(cache.get('k'), undefined)
})

test('cache: overwriting does not change eviction order', () => {
  const cache = createCache({ clock: fakeClock(), maxEntries: 2 })
  cache.set('a', 'A')
  cache.set('b', 'B')
  cache.set('a', 'A2')
  cache.set('c', 'C')
  assert.equal(cache.get('a'), undefined, 'a was the oldest first-inserted key')
  assert.equal(cache.get('b'), 'B')
  assert.equal(cache.get('c'), 'C')
})

test('cache: read-through caches the fetched value', () => {
  const cache = createCache({ clock: fakeClock() })
  let fetches = 0
  const source = { fetch: (key) => { fetches += 1; return `value:${key}` } }
  assert.equal(readThrough(cache, source, 'user:1'), 'value:user:1')
  assert.equal(readThrough(cache, source, 'user:1'), 'value:user:1')
  assert.equal(fetches, 1)
})

