/**
 * Key normalization for the cache. Per the README: trim surrounding
 * whitespace only — case is significant.
 */
export function normalizeKey(key) {
  return key.trim().toLowerCase()
}

import { normalizeKey } from './keys.js'
import { systemClock } from './clock.js'

/**
 * TTL cache with FIFO eviction. Semantics are defined by the README;
 * expiry is `>= ttlMs` and purging is lazy on access.
 */
export function createCache({ clock = systemClock(), ttlMs = 60_000, maxEntries = 100 } = {}) {
  const entries = new Map()

  function get(key) {
    const normalized = normalizeKey(key)
    const entry = entries.get(normalized)
    if (entry === undefined) return undefined
    if (clock.now() - entry.createdAt >= ttlMs) {
      entries.delete(normalized)
      return undefined
    }
    return entry.value
  }

  function set(key, value) {
    const normalized = normalizeKey(key)
    const existing = entries.get(normalized)
    if (existing !== undefined) {
      existing.value = value
      existing.createdAt = clock.now()
      return
    }
    entries.set(normalized, { value, createdAt: clock.now() })
    while (entries.size > maxEntries) {
      const oldest = entries.keys().next().value
      entries.delete(oldest)
    }
  }

  return {
    get,
    set,
    has: (key) => get(key) !== undefined,
    size: () => entries.size,
  }
}

/** Injectable clock seam. The real clock; tests pass their own `{ now() }`. */
export function systemClock() {
  return { now: () => Date.now() }
}

/** Read-through helper: return the cached value or fetch, store and return it. */
export function readThrough(cache, source, key) {
  const cached = cache.get(key)
  if (cached !== undefined) return cached
  const value = source.fetch(key)
  cache.set(key, value)
  return value
}

